// FR-4: every message is processed exactly once, even when the work is slow.
//
// The cursor is claimed from the bridge BEFORE anything slow runs. n8n's own
// static data cannot do this: it is only written when an execution finishes,
// so while a 3-minute CV review was in flight, eight more 15-second polls all
// read the same stale cursor and reprocessed the same CV. The bridge writes
// the claim synchronously under a lock, so exactly one execution can win.
//
// Returning [] stops the branch, so nothing is sent when nothing is new.

const cfg = $('Config').first().json;

const msgs = [];
for (const item of $input.all()) {
  const arr = Array.isArray(item.json) ? item.json : [item.json];
  for (const m of arr) {
    if (m && m.id) msgs.push(m);
  }
}

// Snowflakes are numeric strings - compare as BigInt, never lexically.
msgs.sort((a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : 1));

// Ignore Rafid's own replies, or it would answer itself every 15 seconds.
const human = msgs.filter((m) => !(m.author && m.author.bot));
if (human.length === 0) return [];

// Newest message only. Anything older is either already handled or superseded.
const m = human[human.length - 1];

const claim = await this.helpers.httpRequest({
  method: 'POST',
  url: `${cfg.bridge}/claim`,
  body: { message_id: m.id },
  json: true,
});

if (!claim || claim.claimed !== true) return [];

const atts = (m.attachments || []).filter((a) => /\.pdf$/i.test(a.filename || ''));

return [{
  json: {
    message_id: m.id,
    content: m.content || '',
    is_first_contact: claim.is_first_contact === true,
    session_id: claim.session_id || null,
    has_cv: atts.length > 0,
    attachment_name: atts.length ? atts[0].filename : null,
    attachment_url: atts.length ? atts[0].url : null,
    cv_name: atts.length ? `cv-${m.id}.pdf` : null,
    dm_channel_id: cfg.dm_channel_id,
    workspace: cfg.workspace,
    bridge: cfg.bridge,
  },
}];

// Not a CV: resume the existing Claude Code session. This is how intake answers,
// the "yes fix it" approval and general questions are all handled - Claude Code
// owns the conversation, n8n just carries the text.

const m = $('Pick New Messages').first().json;

let sessionId = m.session_id;
let prompt;

if (!sessionId) {
  // Chatting before any CV was sent. Start a session so Rafid can still answer.
  sessionId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : ((r & 0x3) | 0x8);
    return v.toString(16);
  });

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${m.bridge}/state`,
    body: { patch: { session_id: sessionId } },
    json: true,
  });

  prompt = [
    'You are Rafid, a helper in a Discord DM. You review and rewrite CVs, then match them against live freelance projects.',
    'No CV has been sent yet - if they are ready, ask them to send one as a PDF.',
    'Keep replies under 1200 characters, plain text with light Discord markdown, no code fences.',
    '',
    'The person said:',
    m.content,
  ].join('\n');
} else {
  prompt = [
    m.content,
    '',
    '(Reminder: you are Rafid in a Discord DM. Under 1800 characters, no code fences.',
    'Check their answers for missing units, unclear attribution and vague quantifiers.',
    'If anything is unclear and you have not already asked once, send ONE clarifying',
    'message naming exactly what you need. Otherwise use a [bracketed placeholder].',
    'Never estimate and never resolve an ambiguity in the flattering direction.',
    'If this message approves the rewrite, run the cv-optimizer skill on the same CV',
    'and deliver ===SUMMARY=== plus BOTH ===FILE:rafid-cv=== and ===FILE:rafid-changes===.',
    'The optimised CV must stay under 3000 characters so it fits on one page.)',
  ].join('\n');
}

return [{ json: { ...m, session_id: sessionId, prompt } }];

// R-5 discipline: never trust the shape of an LLM response. Validate first,
// then decide whether this turn is chat or a document delivery.
//
// One parser serves both skills: the review sends one ===FILE:=== block, the
// optimizer sends two. Adding a document type needs no new nodes.

const r = $input.first().json;
const m = $('Pick New Messages').first().json;

if (!r || r.ok !== true) {
  throw new Error('Bridge call failed: ' + JSON.stringify(r && r.error ? r.error : r).slice(0, 400));
}

const out = String(r.output || '').trim();
if (!out) throw new Error('Bridge returned an empty response.');

// style picks the PDF look: 'resume' is dense with a big name and section
// rules, 'report' is the roomier navy-heading document.
const KNOWN = {
  'rafid-review':  { title: 'Rafid - CV Review',    style: 'report', caption: '\u{1F4C4} **Full review**' },
  'rafid-cv':      { title: 'Rafid - Optimised CV', style: 'resume', caption: '\u2728 **Your optimised CV**' },
  'rafid-changes': { title: 'Rafid - What Changed', style: 'report', caption: '\u{1F4DD} **What I changed, and why**' },
};

// Split on every ===FILE:name=== marker, keeping the name.
const parts = out.split(/===FILE:([a-z0-9-]+)===/i);
const head = parts[0];

const files = [];
for (let i = 1; i < parts.length; i += 2) {
  const name = String(parts[i]).toLowerCase();
  const body = String(parts[i + 1] || '').trim();

  // Guard: a marker with no real body would ship an empty PDF.
  if (body.length < 40) continue;

  const meta = KNOWN[name] || { title: 'Rafid Report', style: 'report', caption: '\u{1F4C4} **' + name + '**' };
  files.push({
    doc: name,
    filename: name + '-' + m.message_id + '.pdf',
    title: meta.title,
    style: meta.style,
    caption: meta.caption,
    markdown: body,
  });
}

// The summary is whatever came before the first file marker.
const S = '===SUMMARY===';
let summary = head.includes(S) ? head.slice(head.indexOf(S) + S.length) : head;
summary = summary.trim();
if (!summary) summary = files.length ? 'Here you go:' : out;

// Remember the optimised CV so job matching can use it instead of the original
// upload - that is the point of putting the rewrite in front of the matching.
const cv = files.find((f) => f.doc === 'rafid-cv');
if (cv) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${m.bridge}/state`,
    body: { patch: { cv_optimised_name: cv.filename } },
    json: true,
  });
}

// Discord hard-caps a message at 2000 characters.
if (summary.length > 1900) summary = summary.slice(0, 1890) + '\n\u2026';

return [{
  json: {
    has_files: files.length > 0,
    file_count: files.length,
    files,
    summary,
    session_id: r.session_id,
    resumed: r.resumed,
    message_id: m.message_id,
    dm_channel_id: m.dm_channel_id,
    bridge: m.bridge,
    workspace: m.workspace,
  },
}];

// Fan out: one item per document, so Make PDF / Download PDF / Send each run
// once per file. Parse Output is referenced explicitly because Send Summary is
// an HTTP node and would otherwise have clobbered $json (R-19).

const p = $('Parse Output').first().json;

return p.files.map((f) => ({
  json: { ...f, dm_channel_id: p.dm_channel_id, bridge: p.bridge },
}));

// A demo-day escape hatch (R-3). Typing `reset` in the DM forgets the Claude
// session and the greeting, so the next message starts clean. The cursor is
// deliberately kept, or Rafid would replay the whole DM history.
//
// Deterministic on purpose: no model call, so it works even when Claude Code is
// rate-limited or the skill is mid-failure - which is exactly when you need it.

const m = $('Pick New Messages').first().json;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${m.bridge}/reset`,
  body: {},
  json: true,
});

return [{ json: { ...m } }];

// Validate the router's output. An unparseable answer must not silently become
// a job search - fall back to the conversational path, which can ask.

const m = $('Pick New Messages').first().json;

let raw = $input.first().json.text ?? $input.first().json.output ?? '';
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let intent = 'cv_chat';
let why = 'router output unusable, defaulted to chat';

try {
  const r = JSON.parse(raw);
  if (r.intent === 'find_work' || r.intent === 'cv_chat') {
    intent = r.intent;
    why = r.why || '';
  }
} catch (e) {
  // deliberately not fatal
}

return [{ json: { ...m, intent, why } }];

// Turn the sub-workflow's structured result into one Discord message.
// Discord hard-caps a message at 2000 characters, so pitches are trimmed rather
// than the list being cut short - seeing all five matters more than seeing all
// of any one pitch.

const m = $('Parse Intent').first().json;
const res = $input.first().json || {};
const matches = res.matches || [];

if (matches.length === 0) {
  return [{ json: {
    dm_channel_id: m.dm_channel_id,
    text: '\uD83C\uDF19 Nothing new right now - every live project matching your CV has already been sent. I will keep looking and send one tomorrow morning.',
  } }];
}

const lines = ['\uD83C\uDFAF **' + matches.length + ' projects that fit your CV**', ''];

for (const j of matches) {
  const budget = (j.budget || '').trim();
  lines.push('**' + j.rank + '. ' + j.title + '**  \u2014  ' + j.score + '/100' + (budget ? '  \u00B7  ' + budget : ''));
  let pitch = String(j.pitch || '').trim();
  if (pitch.length > 220) pitch = pitch.slice(0, 217) + '...';
  if (pitch) lines.push('> ' + pitch);
  if (j.url) lines.push(j.url);
  lines.push('');
}

let text = lines.join('\n');
if (text.length > 1950) text = text.slice(0, 1940) + '\n\u2026';

return [{ json: { dm_channel_id: m.dm_channel_id, text } }];
